INSERT INTO official_prompt_versions_staging (prompt_id, version, template_json, template_schema, content_hash, normalized_prompt, negative_prompt, source_json, change_note, created_at, published_at) VALUES ('relocate-portrait-world', 1, '{"blocks":[{"id":"source-photo","sourceId":"source-image","title":"1. Source photo","type":"references","x-connectTo":"primary-output","x-geometry":{"h":220,"w":360,"x":80,"y":80}},{"content":{"controlIds":["brief"]},"id":"creative-brief","title":"2. Creative direction","type":"controls","x-connectTo":"primary-output","x-geometry":{"h":220,"w":360,"x":80,"y":340}},{"content":{"controlIds":["method"]},"id":"visual-method","title":"3. Visual method","type":"controls","x-connectTo":"primary-output","x-geometry":{"h":170,"w":350,"x":500,"y":90}},{"content":{"controlIds":["structure"]},"id":"composition-rule","title":"Composition rule","type":"controls","x-connectTo":"primary-output","x-geometry":{"h":210,"w":350,"x":500,"y":300}},{"content":{"controlIds":["aspect-ratio"]},"id":"format","title":"4. Format","type":"controls","x-connectTo":"primary-output","x-geometry":{"h":170,"w":350,"x":500,"y":550}},{"id":"primary-output","sourceId":"primary","title":"5. Result","type":"output","x-geometry":{"h":620,"w":620,"x":930,"y":100}},{"collapsedByDefault":true,"id":"full-prompt","title":"More control · Full prompt","type":"prompt","x-connectTo":"primary-output","x-geometry":{"h":330,"w":360,"x":80,"y":610}}],"capabilities":["image-to-image","image-edit","variations","upscale"],"category":"photo-transformation","compatibility":{"minimumAppVersion":"0.1.0","templateFamily":"reference-transformation"},"controlGroups":[{"description":"The idea or source needed to begin.","id":"required","label":"Required"},{"description":"A few choices that shape the result.","id":"essentials","label":"Essentials"},{"collapsedByDefault":true,"id":"more-control","label":"More control"}],"controls":[{"binding":{"mode":"variable","target":"brief"},"defaultValue":"Mov