n. Produce one candidate by default and return it to the primary output slot.","body":"Keep the person intact while rebuilding the surrounding world around them. Using the source image as factual ground truth, create an original transformation for {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.","title":"Creative direction","variables":[{"defaultValue":"Move this portrait into a quiet greenhouse during rain","id":"brief","label":"Creative brief","required":true,"type":"text"},{"defaultValue":"subject-preserving relocation","id":"method","label":"Visual method","type":"string"},{"defaultValue":"identity, pose, clothing, framing, and scale remain unchanged","id":"structure","label":"Composition rule","type":"string"}]},"references":[{"acceptedMimeTypes":["image/jpeg","image/png","image/webp"],"description":"The photo to transform.","id":"source-image","instructions":"Use this image as the factual source. Do not invent changes outside the stated brief.","label":"Source image","preserve":["identity and defining features","original composition unless the brief changes it"],"required":true,"role":"source-photo"}],"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Relocate a portrait world"},"status":"starter","tags":["photo transformation","put me somewhere else","keep person change world"],"thumbnail":{"alt":"First-party graphic preview for Relocate a portrait world, illustrating subject-preserving relocation.","assetPath":"/recipe-thumbnails/original-systems/relocate-portrait-world.svg"},"title":"Relocate a portrait world","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["Needs 1 photo","Keeps source identity","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["single-image"],"inputSummary":["One photo and a creative direction"],"intentAliases":["put me somewhere else","keep person change world","relocate portrait background"],"intents":["edit"],"outputKinds":["image"],"preservationNeeds":["identity","composition"],"requiredInputSummary":["One source image and a short direction"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for Relocate a portrait world, illustrating subject-preserving relocation.","src":"/recipe-thumbnails/original-systems/relocate-portrait-world.svg"},"userPromise":"Keep the person intact while rebuilding the surrounding world around them."},"x-presentation":{"advancedControlIds":[],"initialView":"canvas","primaryControlIds":["brief","method","structure","aspect-ratio"],"resultEmphasis":"hero","showPromptByDefault":false}}', 'prompt-canvas.prompt-workspace-template@2', 'sha256:a5adb00b019dffc84f1e5d4f7da6b2bba83abe6d14e480eb760caaae683de08a', 'Keep the person intact while rebuilding the surrounding world around them. Using the source image as factual ground truth, create an original transformation for {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.', NULL, '{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Relocate a portrait world"}', 'Initial official catalog publication.', '2026-09-03T00:00:00Z', '2026-09-03T00:00:00Z');
